// Every sample dataset in one shape: the buyer's lines, the vendors, their replies (files + email text),
// the ideal reading of each reply, and context (internal request, RFI, RFP). Generated by tools/dataset.
import context from "@/seed/context.json";
import demo from "@/seed/demo.json";
import extra from "@/seed/extra.json";
import type { FileKind } from "@/lib/extract/prepare";
import type { InternalRequest } from "@/lib/types";

export type DatasetLine = {
  line_no: number; item_code: string; description: string; category: string; ply: number; gsm: number; bf: number; flute: string;
  length_mm: number; width_mm: number; height_mm: number; qty_p1: number; qty_p2: number; is_new: boolean; spec_key: string;
};
export type DatasetVendor = { code: string; name: string; email: string; reply_format: string; rfi_note: string; rfp_summary: string };
export type DatasetReply = { vendor_code: string; day: number; subject: string; body: string; attachments: { filename: string; kind: FileKind; mime: string }[] };
export type DatasetContract = { vendor_code: string; contract_no: string; valid_from: string; valid_to: string; lines: { line_no: number; spec_key: string; description: string; price: number; unit: string }[] };
export type DatasetRfi = { vendor_name: string; iso_9001: boolean; fsc: boolean; monthly_capacity: string; shortlisted: boolean; reason: string };

export type Dataset = {
  key: string;
  code: string;
  title: string;
  category: string;
  request: InternalRequest;
  lines: DatasetLine[];
  vendors: DatasetVendor[];
  rfi: DatasetRfi[];
  contracts: DatasetContract[];
  replies: DatasetReply[];
  ideal: unknown[];
  clarifications: { vendor_code: string; subject: string; body: string }[];
  idealClarifications: unknown[];
};

const core: Dataset = {
  key: "core",
  code: context.rfx.code.toUpperCase(),
  title: context.rfx.title,
  category: "Corrugated packaging",
  request: context.rfx.internal_request,
  lines: demo.lines,
  vendors: context.vendors,
  rfi: context.rfi,
  contracts: demo.contracts,
  replies: demo.replies as DatasetReply[],
  ideal: demo.ideal_extraction.replies,
  clarifications: demo.clarification_replies,
  idealClarifications: demo.ideal_extraction.clarifications,
};

const extras: Dataset[] = Object.values(extra as Record<string, Omit<Dataset, "clarifications" | "idealClarifications">>).map((d) => ({
  ...d,
  replies: d.replies as DatasetReply[],
  clarifications: [],
  idealClarifications: [],
}));

export const DATASETS: Record<string, Dataset> = Object.fromEntries([core, ...extras].map((d) => [d.key, d]));

export function dataset(key: string | null | undefined): Dataset | null {
  return key ? DATASETS[key] ?? null : null;
}

/** The recorded perfect reading of a sample reply (used for sample RFx and the presenter fallback). */
export function idealReading(key: string, vendorCode: string, kind: "reply" | "clarification"): unknown | null {
  const d = DATASETS[key];
  if (!d) return null;
  const list = kind === "reply" ? d.ideal : d.idealClarifications;
  return (list as { vendor_code: string }[]).find((r) => r.vendor_code === vendorCode) ?? null;
}

export const STANDARD_QUESTIONS = demo.questions;
export const FX_RATE = demo.fx_rate;

/** Internal requests waiting for the buyer: each can become a new RFx with the co-pilot. */
export const PENDING_REQUESTS = ["launch"];

